(self.webpackChunksite=self.webpackChunksite||[]).push([[7031],{416:e=>{"use strict";e.exports=JSON.parse('{"slug":"my-pony","title":"My Pony","authors":[{"name":"Anna Lisia de Almeida Yaguti","contact":null,"contactType":null,"contactUrl":null},{"name":"Veronica Manami Kitamura","contact":"vevekita","contactType":"github","contactUrl":"https://github.com/vevekita"}],"date":1783209600000,"readme":"<ul>\\n<li>To move the character, use the right and left arrow keys on your keyboard.</li>\\n<li>Collect the good apples (orange-colored) that fall from the tree; if you let one fall to the ground, the time will be reduced by 2 seconds.</li>\\n<li>Do not pick up the bad apples (turquoise); if you pick one up, 10 points will be deducted from your score.</li>\\n<li>Rack up as many points as possible!</li>\\n</ul>\\n<p>Have a good game and enjoy yourself!</p>"}')}}]);